"use client";

import type { ChartRoot } from "./chart-utils";
import { useMergedRef } from "../lib/form";
import { useEffect, useEffectEvent, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { animate, motion, useMotionValue } from "motion/react";
import { useChartDirection } from "./chart-pointer";

import { cn } from "../lib/cn";
import { duration, spring } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartAnnouncer, ChartEmpty, LegendKey } from "./chart-parts";
import { useInputSource } from "./chart-fit";
import {
  chartFocusClass,
  clamp,
  decimalsOf,
  enterEase,
  num,
  slotColor,
  useDataChanged,
  useElementWidth,
  resolveInstructions,
  itemAt,
} from "./chart-utils";
import { defaultCompact, useEntrance } from "./heatmap";
import { ChartFigure } from "./chart-figure";

import {
  markGlow,
  solidOverlayClass,
  AboveTip,
  stepKeys,
  defaultCategoryBarLabels,
  type CategoryBarProps,
  THICKNESS,
  CHAR_W,
  fitBoundaryLabels,
} from "./category-bar/model";

export {
  useDeferredDraw,
  markGlow,
  solidOverlayClass,
  solidTipsScope,
  type TipRow,
  AboveTip,
  useStaggerEntrance,
  safeDateFormat,
  safeNumberFormat,
  useTableRows,
  ShowAllRows,
  stepKeys,
  type CategoryBarItem,
  type CategoryBarLabels,
  defaultCategoryBarLabels,
  type CategoryBarProps,
} from "./category-bar/model";
export { type CategoryBarTableProps, CategoryBarTable } from "./category-bar/parts";
/**
 * A single bar split into bands, with an optional marker: where a score, a reading or a
 * forecast sits on a scale of named ranges (Tremor's CategoryBar).
 *
 * - Bands are sized to their values on one scale, 2px apart; the boundary values are printed
 *   under the bar and thinned so they never collide (the two ends always show).
 * - The marker is a pin with a glass bubble (label + value) that never leaves the bar's width;
 *   its number rolls as the pin slides to its value.
 * - Hover, tap or arrow through the bands: each band's span is shown and announced. Every band
 *   and the marker are also in the chart's description, so nothing depends on colour.
 * - Bands grow in from the start, then the pin slides in. Data changes glide (transforms only).
 *   Reduced motion: everything is drawn in place.
 *
 * Keyboard: Tab focuses the bar; the arrow keys move between bands (mirrored in right-to-left), Home and End jump to the first and last, Escape clears.
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; every band and the marker are in the chart's description, and keyboard moves announce a band's span. `CategoryBarTable` is the table view.
 * Glass and motion: the marker bubble is a solid glass-look overlay (no backdrop blur). Reduced motion draws everything in place.
 *
 * @example
 * ```tsx
 * import { CategoryBar } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <CategoryBar
 *       data={[
 *         { label: "Poor", value: 580 },
 *         { label: "Fair", value: 90 },
 *         { label: "Good", value: 130 },
 *       ]}
 *       start={300}
 *       marker={655}
 *       markerLabel="Your score"
 *       aria-label="Credit score on a scale of named ranges"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/category-bar
 */
export function CategoryBar({
  data,
  start = 0,
  marker = null,
  markerLabel,
  showValues = true,
  showLegend = false,
  size = "md",
  format: formatProp,
  locale,
  emptyState,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<CategoryBarProps>) {
  const t = { ...defaultCategoryBarLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const reduced = useSheenReducedMotion();
  const descId = useId();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const barRef = useRef<HTMLDivElement>(null);
  const rtl = useChartDirection(rootRef);
  const play = useEntrance(rootRef, reduced);
  const [active, setActive] = useState<number | null>(null);
  const { fromKeyboard, fromPointer, announce } = useInputSource();

  const bands = useMemo(() => {
    const values = data.map((d) => Math.max(0, num(d.value)));
    return data.map((d, i) => {
      const value = values[i] ?? 0;
      const from = values.slice(0, i).reduce((sum, v) => sum + v, start);
      return { label: d.label, value, from, to: from + value, color: slotColor(d.color ?? i + 1) };
    });
  }, [data, start]);
  const total = bands.reduce((s, b) => s + b.value, 0);
  const end = start + total;
  const signature = bands.map((b) => `${b.label}:${b.value}`).join("|") + `@${start}`;
  const dataChanged = useDataChanged(signature);
  const thickness = THICKNESS[size];
  const hasMarker = marker !== null && Number.isFinite(marker) && total > 0;
  // The real value is shown, announced and tabulated; the pin itself stays on the bar.
  const markerReal = hasMarker ? marker : start;
  const markerValue = clamp(markerReal, start, end);
  const outside = !hasMarker ? 0 : markerReal > end ? 1 : markerReal < start ? -1 : 0;
  const bandOf = (v: number) => bands.find((b, i) => v < b.to || i === bands.length - 1);
  const markerBand = hasMarker && outside === 0 ? bandOf(markerValue) : undefined;

  // Offset from the start of the bar (reading direction), and the physical x for that offset.
  const along = (v: number) => (total > 0 ? ((v - start) / total) * width : 0);
  const px = (v: number) => (rtl ? width - along(v) : along(v));

  /*
   * The pin slides from the start to its value with its number rolling alongside; later changes
   * glide from where it is. One MotionValue drives it: the pin and the bubble move by transform
   * and the number is a text node Motion writes, so the slide never re-renders React or reads
   * layout. The bubble's width comes from a ResizeObserver, not a per-frame measurement.
   */
  const shownMv = useMotionValue(start);
  const pinX = useMotionValue(0);
  const bubbleX = useMotionValue(0);
  const shownText = useMotionValue("");
  const bubbleRef = useRef<HTMLDivElement>(null);
  const [started, setStarted] = useState(false);
  const [bubbleReady, setBubbleReady] = useState(false);
  const geo = useRef({ width, rtl, total, start, end, bubbleW: 0, places: 0, format });
  const [apply] = useState(() => (v: number) => {
    const g = geo.current;
    const a = g.total > 0 ? ((clamp(v, g.start, g.end) - g.start) / g.total) * g.width : 0;
    const p = g.rtl ? g.width - a : a;
    pinX.set(p);
    bubbleX.set(clamp(p - g.bubbleW / 2, 0, Math.max(0, g.width - g.bubbleW)));
    // While it rolls, the number keeps the marker's own precision (no 341.2938 ms mid-way).
    shownText.set(g.format(Number(v.toFixed(g.places))));
  });
  useLayoutEffect(() => {
    geo.current = { ...geo.current, width, rtl, total, start, end, places: decimalsOf(markerReal), format };
    apply(shownMv.get());
  });
  useEffect(() => shownMv.on("change", apply), [shownMv, apply]);
  const entranceDelay = duration.slower * 0.7 + bands.length * 0.06;
  const sized = width > 0;
  // With reduced motion the marker is shown at once: there is no tween to wait for.
  const pinStarted = started || (reduced && hasMarker && play && sized);
  // `started` only picks the first glide: it is read when the effect runs, and flipping it (the timer below does) must not restart that glide.
  const firstGlideDone = useEffectEvent(() => started);
  useEffect(() => {
    if (!hasMarker || !play || !sized) return;
    if (reduced) {
      shownMv.jump(markerReal);
      return;
    }
    if (!firstGlideDone()) {
      // First view: the pin lands once the bands have grown in, then slides from the start.
      let controls: { stop: () => void } | undefined;
      const timer = window.setTimeout(() => {
        shownMv.jump(start);
        setStarted(true);
        controls = animate(shownMv, markerReal, spring.gentle);
      }, entranceDelay * 1000);
      return () => {
        window.clearTimeout(timer);
        controls?.stop();
      };
    }
    const controls = animate(shownMv, markerReal, spring.snappy);
    return () => controls.stop();
  }, [hasMarker, play, reduced, sized, markerReal, start, entranceDelay, shownMv]);
  useLayoutEffect(() => {
    const el = bubbleRef.current;
    if (!el) return;
    const measure = () => {
      geo.current.bubbleW = el.offsetWidth;
      apply(shownMv.get());
      setBubbleReady(true);
    };
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [pinStarted, hasMarker, sized, apply, shownMv]);

  if (bands.length === 0 || total === 0) {
    return (
      <ChartEmpty height={64} aria-label={ariaLabel} className={className}>
        {emptyState ?? t.empty}
      </ChartEmpty>
    );
  }

  const act = active !== null && active < bands.length ? active : null;
  const activeBand = act !== null ? bands[act] : undefined;
  const rangeText = (b: { from: number; to: number }) => t.range(format(b.from), format(b.to));
  const bubbleText = markerLabel ?? t.marker;
  const markerText = format(markerReal);
  const markerWhere =
    outside > 0
      ? t.markerAbove(markerText)
      : outside < 0
        ? t.markerBelow(markerText)
        : markerBand
          ? t.markerIn(markerText, markerBand.label)
          : markerText;
  // Reading the end band also names a marker waiting past that end.
  const markerAt = (i: number) =>
    hasMarker && (markerBand === bands[i] || (outside > 0 && i === bands.length - 1) || (outside < 0 && i === 0));
  const announceText =
    activeBand && act !== null
      ? `${activeBand.label}: ${rangeText(activeBand)}${markerAt(act) ? `. ${bubbleText}: ${outside ? markerWhere : markerText}` : ""}`
      : "";
  const summary = [...bands.map((b) => `${b.label} ${rangeText(b)}`), hasMarker ? `${bubbleText}: ${markerWhere}` : ""]
    .filter(Boolean)
    .join(". ");

  const hitTest = (clientX: number) => {
    const rect = barRef.current?.getBoundingClientRect();
    if (!rect) return null;
    let p = (clientX - rect.left) / Math.max(1, rect.width);
    if (rtl) p = 1 - p;
    const v = start + clamp(p, 0, 1) * total;
    const i = bands.findIndex((b) => v < b.to);
    return i < 0 ? bands.length - 1 : i;
  };

  // Ends of the bar are fully rounded; inner ends are squared off (1px) behind a 2px gap.
  const radius = thickness / 2;
  const geometry = bands.map((b, i) => {
    const a = px(b.from);
    const z = px(b.to);
    const left = Math.min(a, z);
    const physicalFirst = rtl ? i === bands.length - 1 : i === 0;
    const physicalLast = rtl ? i === 0 : i === bands.length - 1;
    const x = left + (physicalFirst ? 0 : 1);
    const w = Math.max(0, Math.abs(z - a) - (physicalFirst ? 0 : 1) - (physicalLast ? 0 : 1));
    return { x, w, rl: physicalFirst ? radius : 1, rr: physicalLast ? radius : 1 };
  });
  const layoutTransition = reduced || !dataChanged ? { duration: 0 } : spring.snappy;

  const boundaries = [start, ...bands.map((b) => b.to)];
  const boundaryText = boundaries.map((v) => format(v));
  const shownBoundaries = fitBoundaryLabels(
    boundaries.map(along),
    boundaryText.map((s) => s.length * CHAR_W),
    width,
  );

  const showPin = hasMarker && pinStarted && width > 0;
  const knob = thickness + 8;
  // Past an end, a small arrow in the bubble and the knob points off the scale.
  const outward = outside === 0 ? 0 : outside > 0 !== rtl ? 1 : -1;
  const arrow = (size: number) => (
    <svg
      aria-hidden
      width={size}
      height={size}
      viewBox="0 0 8 8"
      className="shrink-0 fill-current"
      style={{ transform: outward < 0 ? "scaleX(-1)" : undefined }}
    >
      <path d="M1.5 0.5L7 4L1.5 7.5z" />
    </svg>
  );
  const top = hasMarker ? 40 : 0;
  const hitPad = 6;

  return (
    <div {...rest} ref={rootMerged} className={cn("relative flex w-full min-w-0 flex-col gap-2", className)}>
      {}
      <ChartFigure
        as="div"
        ref={measureRef}
        label={ariaLabel}
        description={resolveInstructions(t.instructions)}
        aria-describedby={descId}

        tabIndex={0}
        className={cn("relative rounded-sheen-sm", chartFocusClass)}
        style={{ paddingTop: top }}
        onKeyDown={(e) => {
          fromKeyboard();
          stepKeys(bands.length, act, rtl, setActive)(e);
        }}
        onBlur={() => setActive(null)}
      >
        <p id={descId} className="sr-only">
          {summary}
        </p>

        {/* Marker bubble (decorative: the description and the announcer carry the value). */}
        {showPin && (
          <motion.div
            ref={bubbleRef}
            aria-hidden
            className={cn(
              solidOverlayClass,
              "pointer-events-none absolute top-0 left-0 flex h-7 w-max max-w-full items-center gap-1.5 rounded-sheen-full px-3 text-xs whitespace-nowrap",
            )}
            initial={reduced ? false : { opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: reduced ? 0 : duration.base }}
            style={{ x: bubbleX, visibility: bubbleReady ? undefined : "hidden" }}
          >
            <span className="min-w-0 truncate text-sheen-fg-muted">{bubbleText}</span>
            <bdi
              className="shrink-0 text-end font-semibold tabular-nums"
              style={{ minWidth: `${markerText.length}ch` }}
            >
              <motion.span>{shownText}</motion.span>
            </bdi>
            {outward !== 0 && <span className="text-sheen-fg-muted">{arrow(8)}</span>}
          </motion.div>
        )}

        <div
          ref={barRef}
          className="relative w-full touch-pan-y touch-pinch-zoom"
          style={{ paddingBlock: hitPad }}
          onPointerMove={(e) => {
            fromPointer();
            setActive(hitTest(e.clientX));
          }}
          onPointerDown={(e) => {
            fromPointer();
            setActive(hitTest(e.clientX));
          }}
          onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
        >
          {/* Touch screens: the hit area grows to 44px without moving anything. */}
          <span
            aria-hidden
            className="absolute inset-x-0 hidden any-pointer-coarse:block"
            style={{ top: -(22 - thickness / 2 - hitPad), bottom: -(22 - thickness / 2 - hitPad) }}
          />
          <div aria-hidden className="relative w-full forced-color-adjust-none" style={{ height: thickness }}>
            {width > 0 &&
              bands.map((b, i) => {
                const g = itemAt(geometry, i);
                if (g.w <= 0) return null;
                const dim = act !== null && act !== i;
                return (
                  <motion.div
                    key={`${b.label}\u0000${i}`}
                    layout
                    layoutDependency={signature}
                    className="absolute inset-y-0 origin-left forced-colors:border forced-colors:border-[CanvasText] rtl:origin-right"
                    initial={reduced ? false : { scaleX: 0 }}
                    animate={{ scaleX: play ? 1 : 0, opacity: dim ? 0.38 : 1 }}
                    transition={{
                      layout: layoutTransition,
                      scaleX: reduced
                        ? { duration: 0 }
                        : { duration: duration.slower, ease: enterEase, delay: i * 0.06 },
                      opacity: { duration: reduced ? 0 : duration.fast },
                    }}
                    style={{
                      left: g.x,
                      width: g.w,
                      background: b.color,
                      borderTopLeftRadius: g.rl,
                      borderBottomLeftRadius: g.rl,
                      borderTopRightRadius: g.rr,
                      borderBottomRightRadius: g.rr,
                      filter: act === i ? markGlow(b.color) : undefined,
                    }}
                  />
                );
              })}

            {/* Pin: a knob on the bar (surface fill, ink ring, soft shadow) with a caret under the bubble. */}
            {showPin && (
              <motion.div aria-hidden className="pointer-events-none absolute top-1/2 left-0" style={{ x: pinX }}>
                <svg
                  width={10}
                  height={6}
                  viewBox="0 0 10 6"
                  className="absolute left-[-5px] fill-sheen-fg-muted forced-colors:fill-[CanvasText]"
                  style={{ top: -knob / 2 - 9 }}
                >
                  <path d="M0 0h10L5 6z" />
                </svg>
                <span
                  className="absolute flex items-center justify-center rounded-full border-[3px] border-sheen-fg bg-(--sheen-chart-surface) text-sheen-fg shadow-[0_1px_3px_var(--sheen-shadow-near),0_0_0_2px_var(--sheen-chart-surface)] forced-colors:border-[CanvasText]"
                  style={{ width: knob, height: knob, left: -knob / 2, top: -knob / 2 }}
                >
                  {outward !== 0 && knob >= 16 && arrow(Math.max(5, knob - 10))}
                </span>
              </motion.div>
            )}
          </div>

          {act !== null && activeBand && width > 0 && (
            <AboveTip
              title={activeBand.label}
              rows={[
                { label: "", value: rangeText(activeBand), color: activeBand.color, kind: "rect" },
                ...(markerAt(act) ? [{ label: bubbleText, value: markerText, color: "transparent" }] : []),
              ]}
              x={itemAt(geometry, act).x + itemAt(geometry, act).w / 2}
              y={hitPad - (hasMarker ? 0 : 2)}
              bounds={width}
            />
          )}
        </div>

        {showValues && width > 0 && (
          <div aria-hidden className="relative mt-1 h-4 text-2xs text-sheen-fg-muted tabular-nums">
            {boundaries.map((v, i) =>
              shownBoundaries.has(i) ? (
                <motion.span
                  key={i}
                  className="absolute top-0 left-0 whitespace-nowrap"
                  initial={reduced ? false : { opacity: 0, x: px(v) }}
                  animate={{ opacity: play ? 1 : 0, x: px(v) }}
                  transition={{
                    opacity: reduced ? { duration: 0 } : { duration: duration.base, delay: 0.25 + i * 0.05 },
                    x: reduced || !dataChanged ? { duration: 0 } : spring.snappy,
                  }}
                  style={{
                    translate:
                      i === 0
                        ? rtl
                          ? "-100% 0"
                          : "0 0"
                        : i === boundaries.length - 1
                          ? rtl
                            ? "0 0"
                            : "-100% 0"
                          : "-50% 0",
                  }}
                >
                  <bdi>{boundaryText[i]}</bdi>
                </motion.span>
              ) : null,
            )}
          </div>
        )}
      </ChartFigure>

      {showLegend && (
        <ul aria-hidden className="flex flex-wrap items-center gap-x-4 gap-y-1.5 text-xs text-sheen-fg-muted">
          {bands.map((b, i) => (
            <li key={i} className="flex items-center gap-1.5">
              <LegendKey color={b.color} />
              <span>{b.label}</span>
            </li>
          ))}
        </ul>
      )}
      <ChartAnnouncer text={announce(announceText)} />
    </div>
  );
}

"use client";

import { startTransition, useDeferredValue, useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { useInView } from "motion/react";

import { cn } from "../../lib/cn";
import { duration } from "../../motion/tokens";
import { Button } from "../../button/button";
import { LegendKey, type TooltipRow } from "../chart-parts";
import { enterEase, type ChartColor, type ChartInstructions } from "../chart-utils";

/* ======================================================================
 * Shared by the HTML charts of this group (category bar, tracker, waffle)
 * ====================================================================== */

/**
 * @internal Whether a chart may build its marks yet: once it comes within 200px of the viewport,
 * switched on in a deferred render. The frame paints at once and the marks right after it (React
 * yields while it builds them), and charts further down a long page cost nothing until they come
 * close, so mounting a chart (a page load, a Chart tab coming back) never blocks input.
 *
 * Pass a ref to the chart's root; returns true once it is within 200px of the viewport (set in a deferred render, so the frame paints first). Build marks only when it is true. Not a component: no DOM, keyboard or screen-reader behaviour.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useDeferredDraw } from "./model";
 *
 * function Marks() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   const draw = useDeferredDraw(ref);
 *   return <div ref={ref}>{draw ? "Marks built" : "Placeholder"}</div>;
 * }
 * ```
 *
 * @see /charts/category-bar
 */
export function useDeferredDraw(ref: React.RefObject<Element | null>) {
  const near = useInView(ref, { once: true, margin: "200px" });
  return useDeferredValue(near, false);
}

/** @internal Soft glow on the active mark, dark theme only (light-dark() keeps light marks crisp). Never on glass. */
export const markGlow = (color: string, blur = 6) =>
  `drop-shadow(0 0 ${blur}px light-dark(transparent, color-mix(in oklab, ${color} 75%, transparent)))`;

/**
 * @internal The look of glass (lit rim, specular sheen, deep shadow) on a near-opaque surface,
 * without a backdrop-filter. For overlays that move with the pointer (tooltips, marker
 * bubbles): re-blurring the animated backdrop under them on every move costs frames, they are
 * too small for the blur to show, and they never count against the page's glass budget.
 */
export const solidOverlayClass =
  "border border-(--sheen-glass-border) bg-sheen-surface/95 bg-(image:--sheen-glass-specular) text-sheen-fg " +
  "shadow-[var(--sheen-glass-rim),var(--sheen-glass-2-shadow)] forced-colors:border-[CanvasText]";

/**
 * @internal On a chart's positioned container: the shared glass tooltips inside it (ChartTooltip,
 * ChartTip, the docked readout) render as solid overlays too, for the same reasons.
 */
export const solidTipsScope =
  "[&_.glass-3]:bg-sheen-surface/95! [&_.glass-3]:[backdrop-filter:none]! [&_.glass-3]:[-webkit-backdrop-filter:none]!";

/** A tooltip row of CategoryBar: the usual label, value and colour, plus an optional icon. */
export type TipRow = TooltipRow & { icon?: ReactNode };

/**
 * @internal A tooltip centred above (or below) an anchor, kept inside its positioned parent's
 * width. CSS does the fitting (percentages in the transform are the tooltip's own size), so it
 * never measures layout, however fast it moves; rows never wrap or run off the card edge.
 * Solid, not glass (see solidOverlayClass). Visual only: the chart announces the same values.
 *
 * Props: `title`, `rows` (label, value, colour, optional icon), `x` and `y` (anchor in px inside the positioned parent), `bounds` (that parent's width), `below` (open downwards; default false) and `children` (extra content under the rows).
 * Accessibility and glass: visual only (no pointer events); the chart announces the same values. A solid glass-look overlay with no backdrop blur, so it is cheap to move with the pointer.
 *
 * @example
 * ```tsx
 * import { AboveTip } from "./model";
 *
 * export function Example() {
 *   return (
 *     <div style={{ position: "relative", width: 320, height: 120 }}>
 *       <AboveTip title="Good" rows={[{ label: "Score", value: "640", color: "var(--sheen-chart-1)" }]} x={160} y={60} bounds={320} />
 *     </div>
 *   );
 * }
 * ```
 *
 * @see /charts/category-bar
 */
export function AboveTip({
  title,
  rows,
  x,
  y,
  bounds,
  below = false,
  children,
}: {
  title: string;
  rows: TipRow[];
  /** Anchor in px, relative to the positioned parent. */
  x: number;
  y: number;
  /** Width of the positioned parent. */
  bounds: number;
  /** Open downwards from `y` instead of upwards. */
  below?: boolean;
  /** Extra content under the rows (e.g. a detail line). */
  children?: ReactNode;
}) {
  // Centred on x, then clamped to [0, bounds − its width] (a tooltip wider than the parent sits at 0).
  const left = `clamp(0px, calc(${Math.round(x)}px - 50%), calc(${Math.round(bounds)}px - 100%))`;
  return (
    <div
      aria-hidden
      data-slot="chart-tooltip"
      className={cn(
        solidOverlayClass,
        "pointer-events-none absolute top-0 left-0 z-20 w-max max-w-[min(18rem,100%)] min-w-28 rounded-sheen-md px-3 py-2.5 text-xs",
      )}
      style={{
        transform: `translate(${left}, ${Math.round(y)}px) translateY(${below ? "10px" : "calc(-100% - 10px)"})`,
      }}
    >
      <p className="mb-1.5 font-medium text-sheen-fg-muted">{title}</p>
      <ul className="flex flex-col gap-1">
        {rows.map((row, i) => (
          <li key={i} className="flex items-center gap-2 whitespace-nowrap">
            {row.icon ? (
              <span
                aria-hidden
                className="flex size-3.5 shrink-0 items-center justify-center [&>svg]:size-3.5"
                style={{ color: row.color }}
              >
                {row.icon}
              </span>
            ) : row.color === "transparent" ? (
              <span aria-hidden className="w-3.5 shrink-0" />
            ) : (
              <LegendKey color={row.color} kind={row.kind ?? "rect"} />
            )}
            <span className="font-semibold text-sheen-fg tabular-nums">{row.value}</span>
            {row.label && <span className="text-sheen-fg-muted">{row.label}</span>}
          </li>
        ))}
      </ul>
      {children}
    </div>
  );
}

/**
 * @internal First-view entrance of many small marks (tracker blocks, waffle cells, candles): one Web
 * Animation per `[data-delay]` element (transform + opacity only), started before the first
 * visible paint, so hundreds of marks cost no React renders. Runs once; nothing under reduced
 * motion, and turning reduced motion on mid-way finishes them.
 *
 * Arguments: `ref` (the container), `play` (start now), `reduced` (skip), `keyframes` (the Web Animation keyframes) and `ms` (duration; default the "slow" motion token). Mark each element to animate with a `data-delay` (seconds). Runs once. Not a component: no DOM, keyboard or screen-reader behaviour; with `reduced` nothing animates.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useStaggerEntrance } from "./model";
 *
 * function Blocks({ play, reduced }: { play: boolean; reduced: boolean }) {
 *   const ref = useRef<HTMLDivElement>(null);
 *   useStaggerEntrance(ref, play, reduced, [{ opacity: 0 }, { opacity: 1 }]);
 *   return (
 *     <div ref={ref}>
 *       <span data-delay="0">A</span>
 *       <span data-delay="0.05">B</span>
 *     </div>
 *   );
 * }
 * ```
 *
 * @see /charts/category-bar
 */
export function useStaggerEntrance(
  ref: React.RefObject<HTMLElement | SVGElement | null>,
  play: boolean,
  reduced: boolean,
  keyframes: Keyframe[],
  ms = duration.slow * 1000,
) {
  const done = useRef(false);
  const running = useRef<Animation[]>([]);
  useLayoutEffect(() => {
    if (!play || done.current) return;
    const root = ref.current;
    if (!root) return;
    const marks = root.querySelectorAll<HTMLElement | SVGElement>("[data-delay]");
    if (marks.length === 0) return;
    done.current = true;
    if (reduced || typeof root.animate !== "function") return;
    const easing = `cubic-bezier(${enterEaseCss})`;
    running.current = Array.from(marks, (el) =>
      el.animate(keyframes, { duration: ms, delay: Number(el.dataset.delay ?? 0) * 1000, easing, fill: "backwards" }),
    );
  });
  useEffect(() => {
    if (!reduced) return;
    for (const a of running.current) a.finish();
    running.current = [];
  }, [reduced]);
}

/** The enter easing as a CSS `cubic-bezier` argument list. @internal */
export const enterEaseCss = (enterEase as readonly number[]).join(",");

/** @internal Date formats that fall back to "en" when the locale (or an option such as a time zone) is invalid. */
export function safeDateFormat(locale: string | undefined, options: Intl.DateTimeFormatOptions) {
  try {
    return new Intl.DateTimeFormat(locale ?? "en", options);
  } catch {
    const { timeZone: _ignored, ...rest } = options;
    return new Intl.DateTimeFormat("en", rest);
  }
}

/** @internal Number formats that fall back to "en" when the locale is invalid. */
export function safeNumberFormat(locale: string | undefined, options: Intl.NumberFormatOptions) {
  try {
    return new Intl.NumberFormat(locale ?? "en", options);
  } catch {
    return new Intl.NumberFormat("en", options);
  }
}

/**
 * @internal Rows for a table view that just mounted (the Table tab was opened). The first few
 * render with the tab switch, the rest in a transition right after it (React yields while it
 * renders them), so the tab paints at once. Long tables stop at `cap` rows until the viewer asks
 * for all of them, instead of building hundreds of rows on a click.
 *
 * Arguments: `rows` and `{ first, cap }` (rows shown with the tab switch, default 10; rows shown before "Show all", default 30). Returns `{ rows, hidden, showAll }`; pair `hidden` and `showAll` with ShowAllRows. Not a component: no DOM, keyboard or screen-reader behaviour.
 *
 * @example
 * ```tsx
 * import { useTableRows } from "./model";
 *
 * function Rows({ items }: { items: string[] }) {
 *   const { rows, hidden, showAll } = useTableRows(items);
 *   return (
 *     <>
 *       <ul>
 *         {rows.map((r) => (
 *           <li key={r}>{r}</li>
 *         ))}
 *       </ul>
 *       {hidden > 0 && (
 *         <button type="button" onClick={showAll}>
 *           Show all
 *         </button>
 *       )}
 *     </>
 *   );
 * }
 * ```
 *
 * @see /charts/category-bar
 */
export function useTableRows<T>(rows: readonly T[], { first = 10, cap = 30 }: { first?: number; cap?: number } = {}) {
  const ready = useDeferredValue(true, false);
  const [all, setAll] = useState(false);
  const limit = all ? rows.length : Math.min(rows.length, cap);
  return {
    rows: rows.slice(0, ready ? limit : Math.min(first, limit)),
    /** Rows left out by the cap (0 while the deferred rows are still on their way). */
    hidden: ready ? rows.length - limit : 0,
    showAll: () => startTransition(() => setAll(true)),
  };
}

/**
 * @internal "Show all N rows" under a capped table view.
 *
 * Props: `hidden` (rows left out; renders nothing at 0), `total`, `label(total)` (button text, e.g. "Show all 120 rows") and `onClick`. Keyboard: a normal ghost button (Tab, Enter or Space) with a 44px hit area on touch.
 *
 * @example
 * ```tsx
 * import { ShowAllRows } from "./model";
 *
 * export function Example() {
 *   return <ShowAllRows hidden={90} total={120} label={(n) => `Show all ${n} rows`} onClick={() => {}} />;
 * }
 * ```
 *
 * @see /charts/category-bar
 */
export function ShowAllRows({
  hidden,
  total,
  label,
  onClick,
}: {
  hidden: number;
  total: number;
  label: (n: number) => string;
  onClick: () => void;
}) {
  if (hidden <= 0) return null;
  return (
    <Button
      variant="ghost"
      size="sm"
      className="self-start border border-sheen-control-border any-pointer-coarse:h-11"
      onClick={onClick}
    >
      {label(total)}
    </Button>
  );
}

/** @internal Arrow-key handler over `count` items that follows the reading direction. */
export function stepKeys(
  count: number,
  active: number | null,
  rtl: boolean,
  set: (i: number | null) => void,
  { rowSize = 0 }: { rowSize?: number } = {},
) {
  return (e: React.KeyboardEvent) => {
    if (count <= 0) return;
    const cur = active === null || active >= count ? -1 : active;
    const forward = rtl ? "ArrowLeft" : "ArrowRight";
    const back = rtl ? "ArrowRight" : "ArrowLeft";
    let next: number | null | undefined;
    if (e.key === forward) next = Math.min(count - 1, cur + 1);
    else if (e.key === back) next = cur <= 0 ? 0 : cur - 1;
    else if (e.key === "ArrowDown")
      next = rowSize > 0 && cur >= 0 ? Math.min(count - 1, cur + rowSize) : Math.min(count - 1, cur + 1);
    else if (e.key === "ArrowUp") next = rowSize > 0 && cur >= 0 ? Math.max(0, cur - rowSize) : cur <= 0 ? 0 : cur - 1;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = count - 1;
    else if (e.key === "Escape" && active !== null) next = null;
    if (next === undefined) return;
    e.preventDefault();
    set(next);
  };
}

/* ======================================================================
 * Category bar
 * ====================================================================== */

/** One band of a CategoryBar: its label, its width on the scale and an optional colour slot. */
export type CategoryBarItem = {
  /** Name of the band, e.g. "Good". */
  label: string;
  /** Width of the band on the scale (e.g. 580 → 670 is 90). Negative values count as 0. */
  value: number;
  /** Palette slot (1–8). Defaults to the band's position. Status bands (poor → good) still carry their label. */
  color?: ChartColor;
};

/**
 * Every string CategoryBar speaks or shows, so it can be translated: pass a `Partial` as the `labels`
 * prop. Entries that need a value are functions.
 */
export type CategoryBarLabels = {
  /** Appended to the accessible name. */
  instructions: ChartInstructions;
  /** A band's span, e.g. "580–670". */
  range: (low: string, high: string) => string;
  /** Shown in the marker's bubble and spoken when there's no `markerLabel`. */
  marker: string;
  /** Where the marker falls, e.g. "712, in Good". */
  markerIn: (value: string, band: string) => string;
  /** A marker past either end of the scale, e.g. "99, above the scale". The pin waits at that end. */
  markerAbove: (value: string) => string;
  markerBelow: (value: string) => string;
  /** Table column headers. */
  band: string;
  from: string;
  to: string;
  share: string;
  empty: string;
};

/**
 * The built-in English strings of CategoryBar; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultCategoryBarLabels: CategoryBarLabels = {
  instructions: "Use the arrow keys to read each band.",
  range: (low, high) => (/^[-−]/.test(low) || /^[-−]/.test(high) ? `${low} – ${high}` : `${low}–${high}`),
  marker: "Marker",
  markerIn: (value, band) => `${value}, in ${band}`,
  markerAbove: (value) => `${value}, above the scale`,
  markerBelow: (value) => `${value}, below the scale`,
  band: "Band",
  from: "From",
  to: "To",
  share: "Share",
  empty: "No data",
};

/**
 * Props of CategoryBar. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type CategoryBarProps = {
  /** The bands, start to end. Their values are widths on one scale. */
  data: readonly CategoryBarItem[];
  /** Where the scale starts (e.g. 300 for a credit score). Default 0. */
  start?: number;
  /**
   * A value on the same scale to point at (e.g. the current score). A value past either end
   * keeps its real number (bubble, announcement, table) while the pin waits at that end with
   * an arrow.
   */
  marker?: number | null;
  /** Text in the marker's bubble, before its value (e.g. "Your score"). */
  markerLabel?: string;
  /** Print the values at the band boundaries under the bar. Default true. */
  showValues?: boolean;
  /** Print each band's colour key and name under the bar. Default false. */
  showLegend?: boolean;
  /** Bar thickness: "sm" 6px, "md" 8px (default), "lg" 12px. */
  size?: "sm" | "md" | "lg";
  /** Formats a value for the labels, tooltips and data table: takes the number, returns the text shown. Default: formatCompact in `locale`. */
  format?: (n: number) => string;
  /** Locale of the default number format. Default "en". */
  locale?: string;
  /** Shown when there are no bands. */
  emptyState?: ReactNode;
  /** Override the chart's strings (i18n). */
  labels?: Partial<CategoryBarLabels>;
  /** Names the bar for assistive tech (e.g. "Credit score bands"). */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

/** The bar thickness of each size, in pixels. @internal */
export const THICKNESS = { sm: 6, md: 8, lg: 12 } as const;

/** The average glyph width of the 11px boundary labels, in pixels. @internal */
export const CHAR_W = 6.2; // average glyph width of the 11px boundary labels

/**
 * Which boundary labels fit without colliding: always the two ends, then every boundary whose
 * label clears its neighbours by 8px (in reading order). `xs` are boundary offsets from the start.
 */
export function fitBoundaryLabels(xs: number[], widths: number[], total: number) {
  const n = xs.length;
  const shown = new Set<number>();
  if (n === 0) return shown;
  const box = (i: number) => {
    const w = widths[i] ?? 0;
    // Ends are anchored to the bar's edges; the rest are centred on their boundary.
    const left = i === 0 ? 0 : i === n - 1 ? total - w : (xs[i] ?? 0) - w / 2;
    return [left, left + w] as const;
  };
  shown.add(0);
  if (n > 1 && box(0)[1] + 8 <= box(n - 1)[0]) shown.add(n - 1);
  const endLeft = shown.has(n - 1) ? box(n - 1)[0] : total;
  let prevRight = box(0)[1];
  for (let i = 1; i < n - 1; i++) {
    const [l, r] = box(i);
    if (l >= prevRight + 8 && r <= endLeft - 8) {
      shown.add(i);
      prevRight = r;
    }
  }
  return shown;
}

import { num } from "../chart-utils";
import { ChartValueTable, defaultCompact, defaultPercent } from "../heatmap";
import { defaultCategoryBarLabels, type CategoryBarProps } from "./model";

/* ---------- Table view ---------- */

/**
 * Props of CategoryBarTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type CategoryBarTableProps = Pick<
  CategoryBarProps,
  "data" | "start" | "format" | "locale" | "marker" | "markerLabel" | "labels"
> & {
  /** Formats a share of the total for the data table cells: takes the share, returns the text shown. Default: percentages in `locale`. */
  formatPercent?: (ratio: number) => string;
  /** Hidden caption that names the table for screen readers. */
  caption?: string;
};

/**
 * Every band with its span and share of the scale, then where the marker falls.
 *
 * Props: the bar's `data`, `start`, `marker`, `markerLabel`, `format`, `locale` and `labels`, plus `formatPercent` and `caption` (hidden, names the table). A real table: each band's span and share, then where the marker falls. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { CategoryBarTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <CategoryBarTable data={[{ label: "Poor", value: 580 }, { label: "Good", value: 130 }]} start={300} marker={655} caption="Credit score bands" />
 *   );
 * }
 * ```
 *
 * @see /charts/category-bar
 */
export function CategoryBarTable({
  data,
  start = 0,
  format: formatProp,
  formatPercent: pctProp,
  locale,
  marker,
  markerLabel,
  labels: labelOverrides,
  caption,
}: CategoryBarTableProps) {
  const t = { ...defaultCategoryBarLabels, ...labelOverrides };
  const format = formatProp ?? defaultCompact(locale);
  const pct = pctProp ?? defaultPercent(locale);
  const values = data.map((d) => Math.max(0, num(d.value)));
  const bands = data.map((d, i) => {
    const value = values[i] ?? 0;
    const from = values.slice(0, i).reduce((sum, v) => sum + v, start);
    return { label: d.label, from, to: from + value, value };
  });
  const at = values.reduce((sum, v) => sum + v, start);
  const total = at - start;
  const hasMarker = marker !== null && marker !== undefined && Number.isFinite(marker) && total > 0;
  const value = hasMarker ? marker : start;
  const inBand =
    hasMarker && value >= start && value <= at
      ? bands.find((b, i) => value < b.to || i === bands.length - 1)
      : undefined;
  const where = !hasMarker
    ? ""
    : value > at
      ? t.markerAbove(format(value))
      : value < start
        ? t.markerBelow(format(value))
        : inBand
          ? t.markerIn(format(value), inBand.label)
          : format(value);
  return (
    <div className="flex flex-col gap-3">
      <ChartValueTable
        caption={caption}
        emptyState={t.empty}
        columns={[{ label: t.band }, { label: t.from }, { label: t.to }, { label: t.share }]}
        rows={bands.map((b) => [b.label, format(b.from), format(b.to), pct(total > 0 ? b.value / total : NaN)])}
      />
      {hasMarker && (
        <p className="text-sm text-sheen-fg-muted">
          {markerLabel ?? t.marker}: <span className="font-semibold text-sheen-fg tabular-nums">{where}</span>
        </p>
      )}
    </div>
  );
}

